package ru.nartov.lab6.controller;
import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import ru.nartov.lab6.dto.*;import ru.nartov.lab6.entity.Subject;import ru.nartov.lab6.service.SubjectService;import java.util.List;
@RestController @RequestMapping("/api/subjects") public class SubjectController{private final SubjectService service;public SubjectController(SubjectService s){service=s;}@GetMapping public ResponseEntity<ApiResponse<List<Subject>>> findAll(){return ResponseEntity.ok(ApiResponse.success("Список учебных дисциплин получен.",service.findAll()));}@GetMapping("/{id}")public ResponseEntity<ApiResponse<Subject>> findById(@PathVariable Long id){return ResponseEntity.ok(ApiResponse.success("Дисциплина найдена.",service.findById(id)));}@PostMapping public ResponseEntity<ApiResponse<Subject>> create(@Valid @RequestBody SubjectRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success("Дисциплина успешно создана.",service.create(r)));}@PutMapping("/{id}")public ResponseEntity<ApiResponse<Subject>> update(@PathVariable Long id,@Valid @RequestBody SubjectRequest r){return ResponseEntity.ok(ApiResponse.success("Дисциплина успешно обновлена.",service.update(id,r)));}@DeleteMapping("/{id}")public ResponseEntity<ApiResponse<Void>> delete(@PathVariable Long id){service.delete(id);return ResponseEntity.ok(ApiResponse.success("Дисциплина успешно удалена.",null));}}
